import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/DO-REPEAT.md","filePath":"manual-en/DO-REPEAT.md","lastUpdated":1785684581000}'),s={name:"manual-en/DO-REPEAT.md"};function i(d,e,r,c,m,l){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h3 id="_14-4-do-repeat" tabindex="-1">14.4 DO REPEAT <a class="header-anchor" href="#_14-4-do-repeat" aria-label="Permalink to &quot;14.4 DO REPEAT&quot;">​</a></h3><pre><code>DO REPEAT dummy_name=expansion….
        …
END REPEAT [PRINT].

expansion takes one of the following forms:
        var_list
        num_or_range…
        ’string’…
        ALL

num_or_range takes one of the following forms:
        number
        num1 TO num2
</code></pre><p><code>DO REPEAT</code> repeats a block of code, textually substituting different variables, numbers, or strings into the block with each repetition.</p><p>Specify a dummy variable name followed by an equals sign (‘=’) and the list of replacements. Replacements can be a list of existing or new variables, numbers, strings, or <code>ALL</code> to specify all existing variables. When numbers are specified, runs of increasing integers may be indicated as <code>num1 TO num2</code>, so that ‘1 TO 5’ is short for ‘1 2 3 4 5’.</p><p>Multiple dummy variables can be specified. Each variable must have the same number of replacements.</p><p>The code within <code>DO REPEAT</code> is repeated as many times as there are replacements for each variable. The first time, the first value for each dummy variable is substituted; the second time, the second value for each dummy variable is substituted; and so on.</p><p>Dummy variable substitutions work like macros. They take place anywhere in a line that the dummy variable name occurs. This includes command and subcommand names, so command and subcommand names that appear in the code block should not be used as dummy variable identifiers. Dummy variable substitutions do not occur inside quoted strings, comments, unquoted strings (such as the text on the <code>TITLE</code> or <code>DOCUMENT</code> command), or inside <code>BEGIN DATA</code>…<code>END DATA</code>.</p><p>Substitution occurs only on whole words, so that, for example, a dummy variable PRINT would not be substituted into the word PRINTOUT.</p><p>New variable names used as replacements are not automatically created as variables, but only if used in the code block in a context that would create them, <em>e.g.</em> on a <code>NUMERIC</code> or <code>STRING</code> command or on the left side of a <code>COMPUTE</code> assignment.</p><p>Any command may appear within <code>DO REPEAT</code>, including nested <code>DO REPEAT</code> commands. If <code>INCLUDE</code> or <code>INSERT</code> appears within <code>DO REPEAT</code>, the substitutions do not apply to the included file.</p><p>If <code>PRINT</code> is specified on <code>END REPEAT</code>, the commands after substitutions are made should be printed to the listing file, prefixed by a plus sign (‘+’). This feature is not yet implemented.</p>`,11)])])}const h=a(s,[["render",i]]);export{p as __pageData,h as default};
